(() => {
	'use strict';
	const DATA = {"lang":"en","swaps":[["منصة بث","Path platform"],["لأتمتة الأعمال","For business automation"]],"apps":{"activity":{"This app allows people to see actions related to their files and data in Nextcloud.\n\t\tEach person can configure their individual activity settings in the personal settings,\n\t\tto choose which activity should be pushed to mobile phones, sent via email\n\t\tor whether a daily summary is sent each morning.\n\t\tMore information is available in the Activity documentation.":"This app allows people to see actions related to their files and data in Path platform.\n\t\tEach person can configure their individual activity settings in the personal settings,\n\t\tto choose which activity should be pushed to mobile phones, sent via email\n\t\tor whether a daily summary is sent each morning.\n\t\tMore information is available in the Activity documentation."},"appstore":{"Best Nextcloud integration":"Best Path platform integration","Enabling {suite} requires force enabling the app. This may cause issues with your Nextcloud instance. Are you sure you want to proceed?":"Enabling {suite} requires force enabling the app. This may cause issues with your Path platform instance. Are you sure you want to proceed?","Good Nextcloud integration":"Good Path platform integration","Nextcloud Appstore":"Path platform Appstore","Office suite switching is managed through the Nextcloud All-in-One interface.":"Office suite switching is managed through the Path platform All-in-One interface.","This app is supported via your current Nextcloud subscription.":"This app is supported via your current Path platform subscription."},"bruteforcesettings":{"Brute-force protection is meant to protect Nextcloud servers from attempts to\nguess account passwords in various ways. Besides the obvious \"*let's try a big\nlist of commonly used passwords*\" attack, it also makes it harder to use\nslightly more sophisticated attacks via the reset password form or trying to\nfind app password tokens.\n\nIf triggered, brute-force protection makes requests coming from an IP on a\nbrute-force protected controller with the same API slower for a 24 hour period.\n\nWith this app, the admin can exempt an IP address or range from this\nprotection which can be useful for testing purposes or when there are false\npositives due to a lot of accounts on one IP address.":"Brute-force protection is meant to protect Path platform servers from attempts to\nguess account passwords in various ways. Besides the obvious \"*let's try a big\nlist of commonly used passwords*\" attack, it also makes it harder to use\nslightly more sophisticated attacks via the reset password form or trying to\nfind app password tokens.\n\nIf triggered, brute-force protection makes requests coming from an IP on a\nbrute-force protected controller with the same API slower for a 24 hour period.\n\nWith this app, the admin can exempt an IP address or range from this\nprotection which can be useful for testing purposes or when there are false\npositives due to a lot of accounts on one IP address."},"calendar":{"A Calendar app for Nextcloud":"A Calendar app for Path platform","A Calendar app for Nextcloud. Easily sync events from various devices with your Nextcloud and edit them online.\n\n* 🚀 **Integration with other Nextcloud apps!** Like Contacts, Talk, Tasks, Deck and Circles\n* 🌐 **WebCal Support!** Want to see your favorite team's matchdays in your calendar? No problem!\n* 🙋 **Attendees!** Invite people to your events\n* ⌚ **Free/Busy!** See when your attendees are available to meet\n* ⏰ **Reminders!** Get alarms for events inside your browser and via email\n* 🔍 **Search!** Find your events at ease\n* ☑️ **Tasks!** See tasks or Deck cards with a due date directly in the calendar\n* 🔈 **Talk rooms!** Create an associated Talk room when booking a meeting with just one click\n* 📆 **Appointment booking** Send people a link so they can book an appointment with you [using this app](https://apps.nextcloud.com/apps/appointments)\n* 📎 **Attachments!** Add, upload and view event attachments\n* 🙈 **We’re not reinventing the wheel!** Based on the great [c-dav library](https://github.com/nextcloud/cdav-library), [ical.js](https://github.com/mozilla-comm/ical.js) and [fullcalendar](https://github.com/fullcalendar/fullcalendar) libraries.":"A Calendar app for Path platform. Easily sync events from various devices with your Path platform and edit them online.\n\n* 🚀 **Integration with other Path platform apps!** Like Contacts, Talk, Tasks, Deck and Circles\n* 🌐 **WebCal Support!** Want to see your favorite team's matchdays in your calendar? No problem!\n* 🙋 **Attendees!** Invite people to your events\n* ⌚ **Free/Busy!** See when your attendees are available to meet\n* ⏰ **Reminders!** Get alarms for events inside your browser and via email\n* 🔍 **Search!** Find your events at ease\n* ☑️ **Tasks!** See tasks or Deck cards with a due date directly in the calendar\n* 🔈 **Talk rooms!** Create an associated Talk room when booking a meeting with just one click\n* 📆 **Appointment booking** Send people a link so they can book an appointment with you [using this app](https://apps.nextcloud.com/apps/appointments)\n* 📎 **Attachments!** Add, upload and view event attachments\n* 🙈 **We’re not reinventing the wheel!** Based on the great [c-dav library](https://github.com/nextcloud/cdav-library), [ical.js](https://github.com/mozilla-comm/ical.js) and [fullcalendar](https://github.com/fullcalendar/fullcalendar) libraries.","Access Nextcloud calendars from other apps and devices":"Access Path platform calendars from other apps and devices","Nextcloud Talk":"Path platform Talk","The recurrence definition of this event is not fully supported by Nextcloud. If you edit the recurrence-options, certain recurrences may be lost.":"The recurrence definition of this event is not fully supported by Path platform. If you edit the recurrence-options, certain recurrences may be lost."},"circles":{"Choose from Nextcloud Files":"Choose from Path platform Files","Connect your account to an external OIDC provider to automatically sync your memberships with Nextcloud teams.":"Connect your account to an external OIDC provider to automatically sync your memberships with Path platform teams.","Create your own teams for sharing. Add Nextcloud users, contacts, or anyone via email.":"Create your own teams for sharing. Add Path platform users, contacts, or anyone via email.","Nextcloud Account":"Path platform Account","Nextcloud App":"Path platform App","Nextcloud Group":"Path platform Group","Nextcloud Initialization":"Path platform Initialization","and everything shared with them across Nextcloud.":"and everything shared with them across Path platform."},"cloud_federation_api":{"The Cloud Federation API enables various Nextcloud instances to communicate with each other and to exchange data.":"The Cloud Federation API enables various Path platform instances to communicate with each other and to exchange data."},"contacts":{"A contacts app for Nextcloud":"A contacts app for Path platform","Choose from Nextcloud Files":"Choose from Path platform Files","Create your own teams for sharing. Add Nextcloud users, contacts, or anyone via email.":"Create your own teams for sharing. Add Path platform users, contacts, or anyone via email.","The Nextcloud contacts app is a user interface for Nextcloud's CardDAV server. Easily sync contacts from various devices with your Nextcloud and edit them online.\n\n* 🚀 **Integration with other Nextcloud apps!** Currently Mail and Calendar – more to come.\n* 🎉 **Never forget a birthday!** You can sync birthdays and other recurring events with your Nextcloud Calendar.\n* 👥 **Sharing of Adressbooks!** You want to share your contacts with your friends or coworkers? No problem!\n* 🙈 **We’re not reinventing the wheel!** Based on the great and open SabreDAV library.":"The Path platform contacts app is a user interface for Path platform's CardDAV server. Easily sync contacts from various devices with your Path platform and edit them online.\n\n* 🚀 **Integration with other Path platform apps!** Currently Mail and Calendar – more to come.\n* 🎉 **Never forget a birthday!** You can sync birthdays and other recurring events with your Path platform Calendar.\n* 👥 **Sharing of Adressbooks!** You want to share your contacts with your friends or coworkers? No problem!\n* 🙈 **We’re not reinventing the wheel!** Based on the great and open SabreDAV library."},"core":{"Enter your subscription key in the support app in order to increase the account limit. This does also grant you all additional benefits that Nextcloud Enterprise offers and is highly recommended for the operation in companies.":"Enter your subscription key in the support app in order to increase the account limit. This does also grant you all additional benefits that Path platform Enterprise offers and is highly recommended for the operation in companies.","Failed to add the public link to your Nextcloud":"Failed to add the public link to your Path platform","It looks like you are trying to reinstall your Nextcloud. However the file CAN_INSTALL is missing from your config directory. Please create the file CAN_INSTALL in your config folder to continue.":"It looks like you are trying to reinstall your Path platform. However the file CAN_INSTALL is missing from your config directory. Please create the file CAN_INSTALL in your config folder to continue.","Nextcloud Server":"Path platform Server","The Nextcloud login form is disabled. Use another login option if available or contact your administration.":"The Path platform login form is disabled. Use another login option if available or contact your administration.","The update was unsuccessful. Please report this issue to the <a href=\"https://github.com/nextcloud/server/issues\" target=\"_blank\">Nextcloud community</a>.":"The update was unsuccessful. Please report this issue to the <a href=\"https://github.com/nextcloud/server/issues\" target=\"_blank\">Path platform community</a>.","This community release of Nextcloud is unsupported and push notifications are limited.":"This community release of Path platform is unsupported and push notifications are limited."},"dashboard":{"Start your day informed\n\nThe Nextcloud Dashboard is your starting point of the day, giving you an overview of your upcoming appointments, urgent emails, chat messages, incoming tickets, latest tweets and much more! People can add the widgets they like and change the background to their liking.":"Start your day informed\n\nThe Path platform Dashboard is your starting point of the day, giving you an overview of your upcoming appointments, urgent emails, chat messages, incoming tickets, latest tweets and much more! People can add the widgets they like and change the background to their liking."},"dav":{"Example content serves to showcase the features of Nextcloud. Default content is shipped with Nextcloud, and can be replaced by custom content.":"Example content serves to showcase the features of Path platform. Default content is shipped with Path platform, and can be replaced by custom content.","Expected filesize of %1$s but read (from Nextcloud client) and wrote (to Nextcloud storage) %2$s. Could either be a network problem on the sending side or a problem writing to the storage on the server side.":"Expected filesize of %1$s but read (from Path platform client) and wrote (to Path platform storage) %2$s. Could either be a network problem on the sending side or a problem writing to the storage on the server side.","Welcome to Nextcloud Calendar!\n\nThis is a sample event - explore the flexibility of planning with Nextcloud Calendar by making any edits you want!\n\nWith Nextcloud Calendar, you can:\n- Create, edit, and manage events effortlessly.\n- Create multiple calendars and share them with teammates, friends, or family.\n- Check availability and display your busy times to others.\n- Seamlessly integrate with apps and devices via CalDAV.\n- Customize your experience: schedule recurring events, adjust notifications and other settings.":"Welcome to Path platform Calendar!\n\nThis is a sample event - explore the flexibility of planning with Path platform Calendar by making any edits you want!\n\nWith Path platform Calendar, you can:\n- Create, edit, and manage events effortlessly.\n- Create multiple calendars and share them with teammates, friends, or family.\n- Check availability and display your busy times to others.\n- Seamlessly integrate with apps and devices via CalDAV.\n- Customize your experience: schedule recurring events, adjust notifications and other settings."},"drawio":{"Integrates draw.io diagrams editor with Nextcloud":"Integrates draw.io diagrams editor with Path platform"},"federatedfilesharing":{"Couldn't establish a federated share, it looks like the server to federate with is too old (Nextcloud <= 9).":"Couldn't establish a federated share, it looks like the server to federate with is too old (Path platform <= 9).","Share with me through my #Nextcloud Federated Cloud ID":"Share with me through my #Path platform Federated Cloud ID","Share with me through my #Nextcloud Federated Cloud ID, see {url}":"Share with me through my #Path platform Federated Cloud ID, see {url}","Share with me via Nextcloud":"Share with me via Path platform"},"files_automatedtagging":{"An app for Nextcloud that automatically assigns tags to newly uploaded files based on some conditions.\n\nThe tags can later be used to control retention, file access, automatic script execution and more.\n\n## How it works\nTo define tags, administrators can create and manage a set of rule groups. Each rule group consists of one or more rules combined through operators. Rules can include criteria like file type, size, time and more. A request matches a group if all rules evaluate to true. On uploading a file all defined groups are evaluated and when matching, the given tags are assigned to the file.":"An app for Path platform that automatically assigns tags to newly uploaded files based on some conditions.\n\nThe tags can later be used to control retention, file access, automatic script execution and more.\n\n## How it works\nTo define tags, administrators can create and manage a set of rule groups. Each rule group consists of one or more rules combined through operators. Rules can include criteria like file type, size, time and more. A request matches a group if all rules evaluate to true. On uploading a file all defined groups are evaluated and when matching, the given tags are assigned to the file."},"files_lock":{"Allow your users to temporary lock their files to avoid conflicts while working on shared files.\n\nℹ️ As of Nextcloud 34 this app is bundled with Nextcloud Hub and hence not released through the appstore anymore.":"Allow your users to temporary lock their files to avoid conflicts while working on shared files.\n\nℹ️ As of Path platform 34 this app is bundled with Path platform Hub and hence not released through the appstore anymore."},"files_pdfviewer":{"Directly view PDF documents in your Nextcloud. \nAs an added bonus, this app can also display Adobe Illustrator (.ai) files. \nPowered by [pdf.js](https://mozilla.github.io/pdf.js/)":"Directly view PDF documents in your Path platform. \nAs an added bonus, this app can also display Adobe Illustrator (.ai) files. \nPowered by [pdf.js](https://mozilla.github.io/pdf.js/)"},"files_sharing":{"\"Sending the password by Nextcloud Talk\" for sharing a file or folder failed because Nextcloud Talk is not enabled.":"\"Sending the password by Path platform Talk\" for sharing a file or folder failed because Path platform Talk is not enabled.","Add to your Nextcloud":"Add to your Path platform","Sharing %s sending the password by Nextcloud Talk failed because Nextcloud Talk is not enabled":"Sharing %s sending the password by Path platform Talk failed because Path platform Talk is not enabled","This application enables people to share files within Nextcloud. If enabled, the admin can choose which groups can share files. The applicable people can then share files and folders with other accounts and groups within Nextcloud. In addition, if the admin enables the share link feature, an external link can be used to share files with other people outside of Nextcloud. Admins can also enforce passwords, expirations dates, and enable server to server sharing via share links, as well as sharing from mobile devices.\nTurning the feature off removes shared files and folders on the server for all share recipients, and also on the sync clients and mobile apps. More information is available in the Nextcloud Documentation.":"This application enables people to share files within Path platform. If enabled, the admin can choose which groups can share files. The applicable people can then share files and folders with other accounts and groups within Path platform. In addition, if the admin enables the share link feature, an external link can be used to share files with other people outside of Path platform. Admins can also enforce passwords, expirations dates, and enable server to server sharing via share links, as well as sharing from mobile devices.\nTurning the feature off removes shared files and folders on the server for all share recipients, and also on the sync clients and mobile apps. More information is available in the Path platform Documentation."},"lib":{"Adjusting this setting in php.ini will make Nextcloud run again":"Adjusting this setting in php.ini will make Path platform run again","Please ask your server administrator to check the Nextcloud configuration.":"Please ask your server administrator to check the Path platform configuration."},"logreader":{"A log reader for Nextcloud":"A log reader for Path platform","If you feel this is an error, please verify {setting} in your {config} and check the Nextcloud Administration Manual.":"If you feel this is an error, please verify {setting} in your {config} and check the Path platform Administration Manual.","Log reader for Nextcloud":"Log reader for Path platform"},"mail":{"**💌 A mail app for Nextcloud**\n\n- **🚀 Integration with other Nextcloud apps!** Currently Contacts, Calendar & Files – more to come.\n- **📥 Multiple mail accounts!** Personal and company account? No problem, and a nice unified inbox. Connect any IMAP account.\n- **🔒 Send & receive encrypted mails!** Using the great [Mailvelope](https://mailvelope.com) browser extension.\n- **🙈 We’re not reinventing the wheel!** Based on the great [Horde](https://www.horde.org) libraries.\n- **📬 Want to host your own mail server?** We do not have to reimplement this as you could set up [Mail-in-a-Box](https://mailinabox.email)!\n\n## Ethical AI Rating\n\n### Priority Inbox\n\nPositive:\n* The software for training and inferencing of this model is open source.\n* The model is created and trained on-premises based on the user's own data.\n* The training data is accessible to the user, making it possible to check or correct for bias or optimise the performance and CO2 usage.\n\n### Thread Summaries (opt-in)\n\n**Rating:** 🟢/🟡/🟠/🔴\n\nThe rating depends on the installed text processing backend. See [the rating overview](https://docs.nextcloud.com/server/latest/admin_manual/ai/index.html) for details.\n\nLearn more about the Nextcloud Ethical AI Rating [in our blog](https://nextcloud.com/blog/nextcloud-ethical-ai-rating/).":"**💌 A mail app for Path platform**\n\n- **🚀 Integration with other Path platform apps!** Currently Contacts, Calendar & Files – more to come.\n- **📥 Multiple mail accounts!** Personal and company account? No problem, and a nice unified inbox. Connect any IMAP account.\n- **🔒 Send & receive encrypted mails!** Using the great [Mailvelope](https://mailvelope.com) browser extension.\n- **🙈 We’re not reinventing the wheel!** Based on the great [Horde](https://www.horde.org) libraries.\n- **📬 Want to host your own mail server?** We do not have to reimplement this as you could set up [Mail-in-a-Box](https://mailinabox.email)!\n\n## Ethical AI Rating\n\n### Priority Inbox\n\nPositive:\n* The software for training and inferencing of this model is open source.\n* The model is created and trained on-premises based on the user's own data.\n* The training data is accessible to the user, making it possible to check or correct for bias or optimise the performance and CO2 usage.\n\n### Thread Summaries (opt-in)\n\n**Rating:** 🟢/🟡/🟠/🔴\n\nThe rating depends on the installed text processing backend. See [the rating overview](https://docs.nextcloud.com/server/latest/admin_manual/ai/index.html) for details.\n\nLearn more about the Path platform Ethical AI Rating [in our blog](https://nextcloud.com/blog/nextcloud-ethical-ai-rating/).","A multi value attribute to provision email aliases. For each value an alias is created. Aliases existing in Nextcloud which are not in the LDAP directory are deleted.":"A multi value attribute to provision email aliases. For each value an alias is created. Aliases existing in Path platform which are not in the LDAP directory are deleted.","Google requires OAuth authentication. If your Nextcloud admin has not configured Google OAuth, you can use a Google App Password instead.":"Google requires OAuth authentication. If your Path platform admin has not configured Google OAuth, you can use a Google App Password instead.","Microsoft requires OAuth authentication. Ask your Nextcloud admin to configure Microsoft OAuth in the admin settings.":"Microsoft requires OAuth authentication. Ask your Path platform admin to configure Microsoft OAuth in the admin settings.","Nextcloud Mail":"Path platform Mail","The account for {email} and cached email data will be removed from Nextcloud, but not from your email provider.":"The account for {email} and cached email data will be removed from Path platform, but not from your email provider.","This setting only makes most sense if you use the same user back-end for your Nextcloud and mail server of your organization.":"This setting only makes most sense if you use the same user back-end for your Path platform and mail server of your organization.","💌 A mail app for Nextcloud":"💌 A mail app for Path platform"},"notifications":{"Contact Nextcloud GmbH":"Contact Path platform GmbH","Nextcloud GmbH sponsors a free push notification gateway for private users. To ensure good service, the gateway limits the number of push notifications per server and the limit was reached for this server. For enterprise users, a more scalable gateway is available.":"Path platform GmbH sponsors a free push notification gateway for private users. To ensure good service, the gateway limits the number of push notifications per server and the limit was reached for this server. For enterprise users, a more scalable gateway is available.","Nextcloud GmbH sponsors a free push notification gateway for private users. To ensure good service, the gateway limits the number of push notifications per server. For enterprise users, a more scalable gateway is available. Contact Nextcloud GmbH for more information.":"Path platform GmbH sponsors a free push notification gateway for private users. To ensure good service, the gateway limits the number of push notifications per server. For enterprise users, a more scalable gateway is available. Contact Path platform GmbH for more information.","Play sound when a call started (requires Nextcloud Talk)":"Play sound when a call started (requires Path platform Talk)","This app provides a backend and frontend for the notification API available in Nextcloud.":"This app provides a backend and frontend for the notification API available in Path platform.","This app provides a backend and frontend for the notification API available in Nextcloud.\n\t\tThe API is used by other apps to notify users in the web UI and sync clients about various things. Some examples are:\n\n📬 Federated file sharing: You received a new remote share\n\n📑 Comments: Another user mentioned you in a comment on a file\n\n🚢 Update notification: Available update for an app or nextcloud itself\n\n📣 Announcement center: An announcement was posted by an admin":"This app provides a backend and frontend for the notification API available in Path platform.\n\t\tThe API is used by other apps to notify users in the web UI and sync clients about various things. Some examples are:\n\n📬 Federated file sharing: You received a new remote share\n\n📑 Comments: Another user mentioned you in a comment on a file\n\n🚢 Update notification: Available update for an app or nextcloud itself\n\n📣 Announcement center: An announcement was posted by an admin","We want to keep offering our push notification service for free, but large number of users overload our infrastructure. For this reason we have to rate-limit the use of push notifications. If you need this feature, consider using Nextcloud Enterprise.":"We want to keep offering our push notification service for free, but large number of users overload our infrastructure. For this reason we have to rate-limit the use of push notifications. If you need this feature, consider using Path platform Enterprise."},"office":{"Office overview app for Nextcloud":"Office overview app for Path platform"},"password_policy":{"This check creates a hash of the password and sends the first 5 characters of this hash to the haveibeenpwned.com API to retrieve a list of all hashes that start with those. Then it checks on the Nextcloud instance if the password hash is in the result set.":"This check creates a hash of the password and sends the first 5 characters of this hash to the haveibeenpwned.com API to retrieve a list of all hashes that start with those. Then it checks on the Path platform instance if the password hash is in the result set."},"privacy":{"Your data represents who you are and can easily be abused. We at Nextcloud believe that you have a right to decide what happens with your data. Nextcloud protects your rights as defined in the User Data Manifesto!":"Your data represents who you are and can easily be abused. We at Path platform believe that you have a right to decide what happens with your data. Path platform protects your rights as defined in the User Data Manifesto!"},"provisioning_api":{"This application enables a set of APIs that external systems can use to create, edit, delete and query account\n\t\tattributes, query, set and remove groups, set quota and query total storage used in Nextcloud. Group admin accounts\n\t\tcan also query Nextcloud and perform the same functions as an admin for groups they manage. The API also enables\n\t\tan admin to query for active Nextcloud applications, application info, and to enable or disable an app remotely.\n\t\tOnce the app is enabled, HTTP requests can be used via a Basic Auth header to perform any of the functions\n\t\tlisted above. More information is available in the Provisioning API documentation, including example calls\n\t\tand server responses.":"This application enables a set of APIs that external systems can use to create, edit, delete and query account\n\t\tattributes, query, set and remove groups, set quota and query total storage used in Path platform. Group admin accounts\n\t\tcan also query Path platform and perform the same functions as an admin for groups they manage. The API also enables\n\t\tan admin to query for active Path platform applications, application info, and to enable or disable an app remotely.\n\t\tOnce the app is enabled, HTTP requests can be used via a Basic Auth header to perform any of the functions\n\t\tlisted above. More information is available in the Provisioning API documentation, including example calls\n\t\tand server responses."},"registration":{"User registration\n\nThis app allows users to register a new account.\n\n# Features\n\n- Add users to a given group\n- Allow-list with email domains (including wildcard) to register with\n- Administrator will be notified via email for new user creation or require approval\n- Supports Nextcloud's Client Login Flow v1 and v2 - allowing registration in the mobile Apps and Desktop clients\n\n# Web form registration flow\n\n1. User enters their email address\n2. Verification link is sent to the email address\n3. User clicks on the verification link\n4. User is lead to a form where they can choose their username and password\n5. New account is created and is logged in automatically":"User registration\n\nThis app allows users to register a new account.\n\n# Features\n\n- Add users to a given group\n- Allow-list with email domains (including wildcard) to register with\n- Administrator will be notified via email for new user creation or require approval\n- Supports Path platform's Client Login Flow v1 and v2 - allowing registration in the mobile Apps and Desktop clients\n\n# Web form registration flow\n\n1. User enters their email address\n2. Verification link is sent to the email address\n3. User clicks on the verification link\n4. User is lead to a form where they can choose their username and password\n5. New account is created and is logged in automatically"},"richdocuments":{"Files may still be downloadable through Nextcloud unless restricted otherwise through sharing or access control settings":"Files may still be downloadable through Path platform unless restricted otherwise through sharing or access control settings","Nextcloud Assistant Slide Deck Generator":"Path platform Assistant Slide Deck Generator","Nextcloud Office":"Path platform Office","Nextcloud Office is a powerful Collabora Online based online office suite with collaborative editing, which supports all major documents, spreadsheet and presentation file formats and works together with all modern browsers.":"Path platform Office is a powerful Collabora Online based online office suite with collaborative editing, which supports all major documents, spreadsheet and presentation file formats and works together with all modern browsers.","Nextcloud Office requires a separate server running Collabora Online to provide editing capabilities.":"Path platform Office requires a separate server running Collabora Online to provide editing capabilities.","Nextcloud Office requires a seperate server running Collabora Online to provide editing capabilities.":"Path platform Office requires a seperate server running Collabora Online to provide editing capabilities.","Nextcloud Office spreadsheet generator":"Path platform Office spreadsheet generator","Nextcloud Office text document generator":"Path platform Office text document generator","Nextcloud URL used by Collabora:":"Path platform URL used by Collabora:","Personal Settings for Nextcloud Office":"Personal Settings for Path platform Office","Please check the Collabora Online server log for more details and make sure that Nextcloud can be reached from there.":"Please check the Collabora Online server log for more details and make sure that Path platform can be reached from there.","Quick tryout with Nextcloud docker.":"Quick tryout with Path platform docker.","Templates inside of this directory will be added to the template selector of Nextcloud Office.":"Templates inside of this directory will be added to the template selector of Path platform Office.","The following options within Nextcloud Office will be disabled: Copy, Download, Export, Print":"The following options within Path platform Office will be disabled: Copy, Download, Export, Print","The settings only apply to compatible office files that are opened in Nextcloud Office":"The settings only apply to compatible office files that are opened in Path platform Office","This application can connect to a Collabora Online (or other) server (WOPI-like Client). Nextcloud is the WOPI Host. Please read the documentation to learn more about that.\n\nYou can also edit your documents off-line with the Collabora Office app from the **[Android](https://play.google.com/store/apps/details?id=com.collabora.libreoffice)** and **[iOS](https://apps.apple.com/us/app/collabora-office/id1440482071)** store.":"This application can connect to a Collabora Online (or other) server (WOPI-like Client). Path platform is the WOPI Host. Please read the documentation to learn more about that.\n\nYou can also edit your documents off-line with the Collabora Office app from the **[Android](https://play.google.com/store/apps/details?id=com.collabora.libreoffice)** and **[iOS](https://apps.apple.com/us/app/collabora-office/id1440482071)** store.","You have not configured the allow-list for WOPI requests. Without this setting users may download restricted files via WOPI requests to the Nextcloud server.":"You have not configured the allow-list for WOPI requests. Without this setting users may download restricted files via WOPI requests to the Path platform server.","Your Nextcloud setup is not capable of connecting to the demo servers because:":"Your Path platform setup is not capable of connecting to the demo servers because:"},"serverinfo":{"By default the checks use the same connection as Nextcloud. Give a separate connection here to run them as a user with the rights Nextcloud does not need, for example to read the full server configuration. Leave the host empty to use the default connection.":"By default the checks use the same connection as Path platform. Give a separate connection here to run them as a user with the rights Path platform does not need, for example to read the full server configuration. Leave the host empty to use the default connection.","Nextcloud is not permitted to read the OPcache status (\"opcache.restrict_api\").":"Path platform is not permitted to read the OPcache status (\"opcache.restrict_api\")."},"settings":{"- %.1f GiB available in %s (Nextcloud temporary directory)":"- %.1f GiB available in %s (Path platform temporary directory)","Best Nextcloud integration":"Best Path platform integration","Choose from Nextcloud Files":"Choose from Path platform Files","Detected some missing optional indices. Occasionally new indices are added (by Nextcloud or installed applications) to improve database performance. Adding indices can sometimes take awhile and temporarily hurt performance so this is not done automatically during upgrades. Once the indices are added, queries to those tables should be faster. Use the command `occ db:add-missing-indices` to add them.":"Detected some missing optional indices. Occasionally new indices are added (by Path platform or installed applications) to improve database performance. Adding indices can sometimes take awhile and temporarily hurt performance so this is not done automatically during upgrades. Once the indices are added, queries to those tables should be faster. Use the command `occ db:add-missing-indices` to add them.","Developed by the {communityopen}Nextcloud community{linkclose}, the {githubopen}source code{linkclose} is licensed under the {licenseopen}AGPL{linkclose}.":"Developed by the {communityopen}Path platform community{linkclose}, the {githubopen}source code{linkclose} is licensed under the {licenseopen}AGPL{linkclose}.","Good Nextcloud integration":"Good Path platform integration","If you use third party applications to connect to Nextcloud, please make sure to create and configure an app password for each before enabling second factor authentication.":"If you use third party applications to connect to Path platform, please make sure to create and configure an app password for each before enabling second factor authentication.","Incorrect row format found in your database. ROW_FORMAT=Dynamic offers the best database performances for Nextcloud. Please update row format on the following list: %s.":"Incorrect row format found in your database. ROW_FORMAT=Dynamic offers the best database performances for Path platform. Please update row format on the following list: %s.","It seems like you are running a 32-bit PHP version. Nextcloud needs 64-bit to run well. Please upgrade your OS and PHP to 64-bit!":"It seems like you are running a 32-bit PHP version. Path platform needs 64-bit to run well. Please upgrade your OS and PHP to 64-bit!","It seems like you are running a 32-bit PHP version. Nextcloud needs 64-bit to run well. Please upgrade your OS and PHP to 64-bit! We will no longer block improvements to performance, security and scalability that are incompatible with 32bit support going forward and we expect that Nextcloud Hub 27 Winter (Nextcloud 36) will no longer work on 32bit systems.":"It seems like you are running a 32-bit PHP version. Path platform needs 64-bit to run well. Please upgrade your OS and PHP to 64-bit! We will no longer block improvements to performance, security and scalability that are incompatible with 32bit support going forward and we expect that Path platform Hub 27 Winter (Path platform 36) will no longer work on 32bit systems.","Mail provider enables sending emails directly through the user's personal email account. At present, this functionality is limited to calendar invitations. It requires Nextcloud Mail 4.1 and an email account in Nextcloud Mail that matches the user's email address in Nextcloud.":"Mail provider enables sending emails directly through the user's personal email account. At present, this functionality is limited to calendar invitations. It requires Path platform Mail 4.1 and an email account in Path platform Mail that matches the user's email address in Path platform.","MariaDB version \"%1$s\" detected. MariaDB >=%2$s and <=%3$s is suggested for best performance, stability and functionality with this version of Nextcloud.":"MariaDB version \"%1$s\" detected. MariaDB >=%2$s and <=%3$s is suggested for best performance, stability and functionality with this version of Path platform.","MariaDB version 10.3 detected, this version is end-of-life and only supported as part of Ubuntu 20.04. MariaDB >=%1$s and <=%2$s is suggested for best performance, stability and functionality with this version of Nextcloud.":"MariaDB version 10.3 detected, this version is end-of-life and only supported as part of Ubuntu 20.04. MariaDB >=%1$s and <=%2$s is suggested for best performance, stability and functionality with this version of Path platform.","MariaDB version 10.6 detected, this version is end-of-life and only supported as part of Ubuntu 22.04. MariaDB >=%1$s and <=%2$s is suggested for best performance, stability and functionality with this version of Nextcloud.":"MariaDB version 10.6 detected, this version is end-of-life and only supported as part of Ubuntu 22.04. MariaDB >=%1$s and <=%2$s is suggested for best performance, stability and functionality with this version of Path platform.","MySQL version \"%1$s\" detected. MySQL >=%2$s and <=%3$s is suggested for best performance, stability and functionality with this version of Nextcloud.":"MySQL version \"%1$s\" detected. MySQL >=%2$s and <=%3$s is suggested for best performance, stability and functionality with this version of Path platform.","Nextcloud %d does not support your current version, so be sure to update the database before updating your Nextcloud Server.":"Path platform %d does not support your current version, so be sure to update the database before updating your Path platform Server.","Nextcloud configuration file is writable":"Path platform configuration file is writable","Nextcloud help & privacy resources":"Path platform help & privacy resources","Nextcloud help overview":"Path platform help overview","Nextcloud is not allowed to use the OPcache API. With OPcache enabled, it is highly recommended to include all Nextcloud directories with \"opcache.restrict_api\" or unset this setting to disable OPcache API restrictions, to prevent errors during Nextcloud core or app upgrades.":"Path platform is not allowed to use the OPcache API. With OPcache enabled, it is highly recommended to include all Path platform directories with \"opcache.restrict_api\" or unset this setting to disable OPcache API restrictions, to prevent errors during Path platform core or app upgrades.","Nextcloud profile":"Path platform profile","Nextcloud settings":"Path platform settings","OPcache is configured to remove code comments. With OPcache enabled, \"opcache.save_comments=1\" must be set for Nextcloud to function.":"OPcache is configured to remove code comments. With OPcache enabled, \"opcache.save_comments=1\" must be set for Path platform to function.","Office suite switching is managed through the Nextcloud All-in-One interface.":"Office suite switching is managed through the Path platform All-in-One interface.","Oracle version \"%1$s\" detected. Oracle >=%2$s and <=%3$s is suggested for best performance, stability and functionality with this version of Nextcloud.":"Oracle version \"%1$s\" detected. Oracle >=%2$s and <=%3$s is suggested for best performance, stability and functionality with this version of Path platform.","Please make sure to set the \"overwrite.cli.url\" option in your config.php file to the URL that your users mainly use to access this Nextcloud. Suggestion: \"%s\". Otherwise there might be problems with the URL generation via cron. (It is possible though that the suggested URL is not the URL that your users mainly use to access this Nextcloud. Best is to double check this in any case.)":"Please make sure to set the \"overwrite.cli.url\" option in your config.php file to the URL that your users mainly use to access this Path platform. Suggestion: \"%s\". Otherwise there might be problems with the URL generation via cron. (It is possible though that the suggested URL is not the URL that your users mainly use to access this Path platform. Best is to double check this in any case.)","PostgreSQL version \"%1$s\" detected. PostgreSQL >=%2$s and <=%3$s is suggested for best performance, stability and functionality with this version of Nextcloud.":"PostgreSQL version \"%1$s\" detected. PostgreSQL >=%2$s and <=%3$s is suggested for best performance, stability and functionality with this version of Path platform.","Reasons to use Nextcloud in your organization":"Reasons to use Path platform in your organization","Server identifier isn’t configured. It is recommended if your Nextcloud instance is running on several PHP servers. Add a server ID in your configuration.":"Server identifier isn’t configured. It is recommended if your Path platform instance is running on several PHP servers. Add a server ID in your configuration.","The reverse proxy header configuration is incorrect, or you are accessing Nextcloud from a trusted proxy. If not, this is a security issue and can allow an attacker to spoof their IP address as visible to the Nextcloud.":"The reverse proxy header configuration is incorrect, or you are accessing Path platform from a trusted proxy. If not, this is a security issue and can allow an attacker to spoof their IP address as visible to the Path platform.","The reverse proxy header configuration is incorrect. This is a security issue and can allow an attacker to spoof their IP address as visible to the Nextcloud.":"The reverse proxy header configuration is incorrect. This is a security issue and can allow an attacker to spoof their IP address as visible to the Path platform.","There are some administration imported SSL certificates present, that are not used anymore with Nextcloud 21. They can be imported on the command line via \"occ security:certificates:import\" command. Their paths inside the data directory are shown below.":"There are some administration imported SSL certificates present, that are not used anymore with Path platform 21. They can be imported on the command line via \"occ security:certificates:import\" command. Their paths inside the data directory are shown below.","This app is supported via your current Nextcloud subscription.":"This app is supported via your current Path platform subscription.","This community release of Nextcloud is unsupported and instant notifications are unavailable.":"This community release of Path platform is unsupported and instant notifications are unavailable.","This is the unsupported community build of Nextcloud. Given the size of this instance, performance, reliability and scalability cannot be guaranteed. Push notifications are limited to avoid overloading our free service. Learn more about the benefits of Nextcloud Enterprise at {link}.":"This is the unsupported community build of Path platform. Given the size of this instance, performance, reliability and scalability cannot be guaranteed. Push notifications are limited to avoid overloading our free service. Learn more about the benefits of Path platform Enterprise at {link}.","You are accessing your instance over a secure connection, however your instance is generating insecure URLs. This likely means that your instance is behind a reverse proxy and the Nextcloud `overwrite*` config values are not set correctly.":"You are accessing your instance over a secure connection, however your instance is generating insecure URLs. This likely means that your instance is behind a reverse proxy and the Path platform `overwrite*` config values are not set correctly.","You are currently running PHP %1$s. PHP %2$s is deprecated since Nextcloud %3$s. Nextcloud %4$s may require at least PHP %5$s. Please upgrade to one of the officially supported PHP versions provided by the PHP Group as soon as possible.":"You are currently running PHP %1$s. PHP %2$s is deprecated since Path platform %3$s. Path platform %4$s may require at least PHP %5$s. Please upgrade to one of the officially supported PHP versions provided by the PHP Group as soon as possible.","Your instance is generating insecure URLs. If you access your instance over HTTPS, this likely means that your instance is behind a reverse proxy and the Nextcloud `overwrite*` config values are not set correctly.":"Your instance is generating insecure URLs. If you access your instance over HTTPS, this likely means that your instance is behind a reverse proxy and the Path platform `overwrite*` config values are not set correctly.","Your web server is not properly set up to deliver .{extension} files. This is typically an issue with the Nginx configuration. For Nextcloud 15 it needs an adjustment to also deliver .{extension} files. Compare your Nginx configuration to the recommended configuration in our documentation.":"Your web server is not properly set up to deliver .{extension} files. This is typically an issue with the Nginx configuration. For Path platform 15 it needs an adjustment to also deliver .{extension} files. Compare your Nginx configuration to the recommended configuration in our documentation."},"spreed":{"# Welcome to Nextcloud Talk\n\nNextcloud Talk is a private and powerful messaging app that integrates with Nextcloud. Chat in private or group conversations, collaborate over voice and video calls, organize webinars and events, customize your conversations and more.":"# Welcome to Path platform Talk\n\nPath platform Talk is a private and powerful messaging app that integrates with Path platform. Chat in private or group conversations, collaborate over voice and video calls, organize webinars and events, customize your conversations and more.","## Welcome to Nextcloud Talk!\nIn this conversation you will be informed about new features available in Nextcloud Talk.":"## Welcome to Path platform Talk!\nIn this conversation you will be informed about new features available in Path platform Talk.","## ✨ Do more with Smart Picker\n\nSimply type \"/\" or go to the \"+\" menu to open the Smart Picker where you can attach various content to your messages. You can configure the Smart Picker to be able to add items from Nextcloud apps, GIFs, map locations, AI generated content and much more.":"## ✨ Do more with Smart Picker\n\nSimply type \"/\" or go to the \"+\" menu to open the Smart Picker where you can attach various content to your messages. You can configure the Smart Picker to be able to add items from Path platform apps, GIFs, map locations, AI generated content and much more.","## 🎨 Format texts to create rich messages\n\nIn Nextcloud Talk, you can use Markdown syntax to format your messages. For example, apply **bold** or *italic* formatting, or `highlight texts as code`. You can even create tables and add headings to your text.\n\nNeed to fix a typo or change formatting? Edit your message by clicking \"Edit message\" in the message menu.":"## 🎨 Format texts to create rich messages\n\nIn Path platform Talk, you can use Markdown syntax to format your messages. For example, apply **bold** or *italic* formatting, or `highlight texts as code`. You can even create tables and add headings to your text.\n\nNeed to fix a typo or change formatting? Edit your message by clicking \"Edit message\" in the message menu.","## 🔗 Add attachments and links\n\nAttach files from your Nextcloud Hub using the \"+\" button. Share items from Files and various Nextcloud apps. Some apps even support interactive widgets, for example, the Text app.":"## 🔗 Add attachments and links\n\nAttach files from your Path platform Hub using the \"+\" button. Share items from Files and various Path platform apps. Some apps even support interactive widgets, for example, the Text app.","**Nextcloud Talk** is a secure, self-hosted communication platform that integrates seamlessly with the Nextcloud ecosystem.\n\n#### Key Features of Nextcloud Talk:\n\n* Chat and messaging in private and group chats\n* Voice and video calls\n* File sharing and integration with other Nextcloud apps\n* Customizable conversation settings, moderation and privacy controls\n* Web, desktop and mobile (iOS and Android)\n* Private & secure communication\n\n Find out more in the [user documentation](https://docs.nextcloud.com/server/latest/user_manual/en/talk/index.html).":"**Path platform Talk** is a secure, self-hosted communication platform that integrates seamlessly with the Path platform ecosystem.\n\n#### Key Features of Path platform Talk:\n\n* Chat and messaging in private and group chats\n* Voice and video calls\n* File sharing and integration with other Path platform apps\n* Customizable conversation settings, moderation and privacy controls\n* Web, desktop and mobile (iOS and Android)\n* Private & secure communication\n\n Find out more in the [user documentation](https://docs.nextcloud.com/server/latest/user_manual/en/talk/index.html).","- Introducing the Nextcloud Talk desktop client for Windows, macOS and Linux: %s":"- Introducing the Path platform Talk desktop client for Windows, macOS and Linux: %s","- Summarize call recordings and unread messages in chats with the Nextcloud Assistant":"- Summarize call recordings and unread messages in chats with the Path platform Assistant","Chat, video & audio-conferencing using WebRTC\n\n* 💬 **Chat** Nextcloud Talk comes with a simple text chat, allowing you to share or upload files from your Nextcloud Files app or local device and mention other participants.\n* 👥 **Private, group, public and password protected calls!** Invite someone, a whole group or send a public link to invite to a call.\n* 🌐 **Federated chats** Chat with other Nextcloud users on their servers\n* 💻 **Screen sharing!** Share your screen with the participants of your call.\n* 🚀 **Integration with other Nextcloud apps** like Files, Calendar, User status, Dashboard, Flow, Maps, Smart picker, Contacts, Deck, and many more.\n* 🌉 **Sync with other chat solutions** With [Matterbridge](https://github.com/42wim/matterbridge/) being integrated in Talk, you can easily sync a lot of other chat solutions to Nextcloud Talk and vice-versa.":"Chat, video & audio-conferencing using WebRTC\n\n* 💬 **Chat** Path platform Talk comes with a simple text chat, allowing you to share or upload files from your Path platform Files app or local device and mention other participants.\n* 👥 **Private, group, public and password protected calls!** Invite someone, a whole group or send a public link to invite to a call.\n* 🌐 **Federated chats** Chat with other Path platform users on their servers\n* 💻 **Screen sharing!** Share your screen with the participants of your call.\n* 🚀 **Integration with other Path platform apps** like Files, Calendar, User status, Dashboard, Flow, Maps, Smart picker, Contacts, Deck, and many more.\n* 🌉 **Sync with other chat solutions** With [Matterbridge](https://github.com/42wim/matterbridge/) being integrated in Talk, you can easily sync a lot of other chat solutions to Path platform Talk and vice-versa.","Error: System times of Nextcloud server and High-performance backend server are out of sync. Please make sure that both servers are connected to a time-server or manually synchronize their time.":"Error: System times of Path platform server and High-performance backend server are out of sync. Please make sure that both servers are connected to a time-server or manually synchronize their time.","Error: System times of Nextcloud server and Recording backend server are out of sync. Please make sure that both servers are connected to a time-server or manually synchronize their time.":"Error: System times of Path platform server and Recording backend server are out of sync. Please make sure that both servers are connected to a time-server or manually synchronize their time.","It is highly recommended to configure a memory cache when running Nextcloud Talk with a High-performance backend.":"It is highly recommended to configure a memory cache when running Path platform Talk with a High-performance backend.","It is highly recommended to set up a distributed cache when using Nextcloud Talk with a High-performance backend.":"It is highly recommended to set up a distributed cache when using Path platform Talk with a High-performance backend.","Join conversations from remote Nextcloud servers":"Join conversations from remote Path platform servers","Nextcloud Talk Federation was updated.":"Path platform Talk Federation was updated.","Nextcloud Talk setup not complete":"Path platform Talk setup not complete","Nextcloud Talk was updated, you cannot start or join a call.":"Path platform Talk was updated, you cannot start or join a call.","Nextcloud Talk was updated.":"Path platform Talk was updated.","Nextcloud URL":"Path platform URL","Nextcloud base URL":"Path platform base URL","Nextcloud is in maintenance mode.":"Path platform is in maintenance mode.","Nextcloud portal":"Path platform portal","Nextcloud user":"Path platform user","No High-performance backend configured - Running Nextcloud Talk without the High-performance backend only scales for very small calls (max. 2-3 participants). Please set up the High-performance backend to ensure calls with multiple participants work seamlessly.":"No High-performance backend configured - Running Path platform Talk without the High-performance backend only scales for very small calls (max. 2-3 participants). Please set up the High-performance backend to ensure calls with multiple participants work seamlessly.","Our partner Struktur AG provides a service where a hosted signaling server can be requested. For this you only need to fill out the form below and your Nextcloud will request it. Once the server is set up for you the credentials will be filled automatically. This will overwrite the existing signaling server settings.":"Our partner Struktur AG provides a service where a hosted signaling server can be requested. For this you only need to fill out the form below and your Path platform will request it. Once the server is set up for you the credentials will be filled automatically. This will overwrite the existing signaling server settings.","The browser you're using is not fully supported by Nextcloud Talk. Please use the latest version of Mozilla Firefox, Microsoft Edge, Google Chrome, Opera or Apple Safari.":"The browser you're using is not fully supported by Path platform Talk. Please use the latest version of Mozilla Firefox, Microsoft Edge, Google Chrome, Opera or Apple Safari.","There is already a trial registered for this Nextcloud instance.":"There is already a trial registered for this Path platform instance.","URL of this Nextcloud instance":"URL of this Path platform instance","You are trying to join a conversation while having an active session in another window or device. This is currently not supported by Nextcloud Talk. What do you want to do?":"You are trying to join a conversation while having an active session in another window or device. This is currently not supported by Path platform Talk. What do you want to do?","You can install the Matterbridge to link Nextcloud Talk to some other services, visit their {linkstart1}GitHub page{linkend} for more details. Downloading and installing the app can take a while. In case it times out, please install it manually from the {linkstart2}Nextcloud App Store{linkend}.":"You can install the Matterbridge to link Path platform Talk to some other services, visit their {linkstart1}GitHub page{linkend} for more details. Downloading and installing the app can take a while. In case it times out, please install it manually from the {linkstart2}Path platform App Store{linkend}.","You joined the conversation in another window or device. This is currently not supported by Nextcloud Talk so this session was closed.":"You joined the conversation in another window or device. This is currently not supported by Path platform Talk so this session was closed."},"tasks":{"Once enabled, a new Tasks menu will appear in your Nextcloud apps menu. From there you can add and delete tasks, edit their title, description, start and due dates and mark them as important. Tasks can be shared between users. Tasks can be synchronized using CalDav (each task list is linked to an Nextcloud calendar, to sync it to your local client: Thunderbird, Evolution, KDE Kontact, iCal … - just add the calendar as a remote calendar in your client). You can download your tasks as ICS files using the download button for each calendar.":"Once enabled, a new Tasks menu will appear in your Path platform apps menu. From there you can add and delete tasks, edit their title, description, start and due dates and mark them as important. Tasks can be shared between users. Tasks can be synchronized using CalDav (each task list is linked to an Path platform calendar, to sync it to your local client: Thunderbird, Evolution, KDE Kontact, iCal … - just add the calendar as a remote calendar in your client). You can download your tasks as ICS files using the download button for each calendar.","The Tasks app for Nextcloud":"The Tasks app for Path platform"},"text":{"** 📝 Collaborative document editing!**\n\n- **📝 Focused writing:** No distractions, only the formatting you need.\n- **🙋 Work together:** Share and collaborate with friends and colleagues, no matter if they use Nextcloud or not!\n- **💾 Open format:** Files are saved as [Markdown](https://en.wikipedia.org/wiki/Markdown), so you can edit them from any other text app too.\n- **✊ Strong foundation:** We use [🐈 tiptap](https://tiptap.scrumpy.io) which is based on [🦉 ProseMirror](https://prosemirror.net) – huge thanks to them!":"** 📝 Collaborative document editing!**\n\n- **📝 Focused writing:** No distractions, only the formatting you need.\n- **🙋 Work together:** Share and collaborate with friends and colleagues, no matter if they use Path platform or not!\n- **💾 Open format:** Files are saved as [Markdown](https://en.wikipedia.org/wiki/Markdown), so you can edit them from any other text app too.\n- **✊ Strong foundation:** We use [🐈 tiptap](https://tiptap.scrumpy.io) which is based on [🦉 ProseMirror](https://prosemirror.net) – huge thanks to them!","Nextcloud Assistant":"Path platform Assistant","Nextcloud Assistant result copied":"Path platform Assistant result copied","Nextcloud Text":"Path platform Text"},"theming":{"Adjust the Nextcloud theme":"Adjust the Path platform theme"},"user_migration":{"**👤➡ User migration app for Nextcloud**\n\nThis app allows users to easily migrate from one instance to another using an export of their account.\n\n- **🐱 Log in to cat.example.com/nextcloud**\n- **⚙ Go into `Personal settings` > `Data migration`**\n- **☑ Select what you want to export** (settings, files, profile information, profile picture, calendars, contacts…)\n- **⚙ Start the export** and wait for the server to process it\n- **📁 Download the resulting file called `user.nextcloud_export`**\n- **🐶 Open an account on dog.example.com/nextcloud**\n- **🡅 Upload `user.nextcloud_export` into your files**\n- **⚙ Go into `Personal settings` > `Data migration` and start the import**\n- **🎉 Enjoy your stay on your new instance** and close you old account":"**👤➡ User migration app for Path platform**\n\nThis app allows users to easily migrate from one instance to another using an export of their account.\n\n- **🐱 Log in to cat.example.com/nextcloud**\n- **⚙ Go into `Personal settings` > `Data migration`**\n- **☑ Select what you want to export** (settings, files, profile information, profile picture, calendars, contacts…)\n- **⚙ Start the export** and wait for the server to process it\n- **📁 Download the resulting file called `user.nextcloud_export`**\n- **🐶 Open an account on dog.example.com/nextcloud**\n- **🡅 Upload `user.nextcloud_export` into your files**\n- **⚙ Go into `Personal settings` > `Data migration` and start the import**\n- **🎉 Enjoy your stay on your new instance** and close you old account"},"viewer":{"Show your latest holiday photos and videos like in the movies, show a glimpse of your latest novel directly from your Nextcloud, choose the best GIF of your collection thanks to the direct preview of your favorites files and many more!":"Show your latest holiday photos and videos like in the movies, show a glimpse of your latest novel directly from your Path platform, choose the best GIF of your collection thanks to the direct preview of your favorites files and many more!"},"webhook_listeners":{"Nextcloud Webhook Support":"Path platform Webhook Support","Nextcloud webhook support":"Path platform webhook support","Set up webhooks that automatically notify external services whenever certain events - like file changes - occur within Nextcloud. By configuring these webhooks, administrators can specify which actions in their Nextcloud instance should trigger notifications and where those notifications should be sent, enabling seamless integration with other platforms and automating workflows.\n\nThe app works by monitoring Nextcloud's event system and dispatching HTTP requests (webhooks) containing relevant event data to the specified endpoints whenever a configured event takes place. This approach makes it easy to connect Nextcloud with external tools, allowing for real-time interactions without needing to manually check for updates or changes.\n\nAdministrators can configure webhook listeners via the app's OCS API. The app also provides a command-line tool to list currently configured webhooks. There are no Web UI settings.":"Set up webhooks that automatically notify external services whenever certain events - like file changes - occur within Path platform. By configuring these webhooks, administrators can specify which actions in their Path platform instance should trigger notifications and where those notifications should be sent, enabling seamless integration with other platforms and automating workflows.\n\nThe app works by monitoring Path platform's event system and dispatching HTTP requests (webhooks) containing relevant event data to the specified endpoints whenever a configured event takes place. This approach makes it easy to connect Path platform with external tools, allowing for real-time interactions without needing to manually check for updates or changes.\n\nAdministrators can configure webhook listeners via the app's OCS API. The app also provides a command-line tool to list currently configured webhooks. There are no Web UI settings."},"workflowengine":{"Nextcloud workflow engine":"Path platform workflow engine"}},"noFile":[]};
	const g = globalThis;
	g._oc_l10n_registry_translations ??= {};
	g._oc_l10n_registry_plural_functions ??= {};
	if (g._oc_l10n_registry_translations.__pathlocale) return;

	const plural = DATA.lang === 'ar'
		? (n) => (n === 0 ? 0 : n === 1 ? 1 : n === 2 ? 2 : (n % 100 >= 3 && n % 100 <= 10) ? 3 : (n % 100 >= 11 && n % 100 <= 99) ? 4 : 5)
		: (n) => (n === 1 ? 0 : 1);
	const own = (app) => typeof app === 'string' && Object.prototype.hasOwnProperty.call(DATA.apps, app);
	const empty = {};
	const cache = new WeakMap();
	const emptyMerged = {};

	const real = g._oc_l10n_registry_translations;
	const proxy = new Proxy(real, {
		get(target, app, receiver) {
			if (app === '__pathlocale') return true;
			const base = Reflect.get(target, app, receiver);
			if (!own(app)) return base;
			const key = base ?? empty;
			let byApp = cache.get(key);
			if (!byApp) { byApp = {}; cache.set(key, byApp); }
			return byApp[app] ??= { ...(base ?? {}), ...DATA.apps[app] };
		},
	});
	g._oc_l10n_registry_translations = proxy;

	// apps with a dictionary of ours need a plural function even when Nextcloud registered none
	for (const app of Object.keys(DATA.apps)) {
		if (typeof g._oc_l10n_registry_plural_functions[app] !== 'function') g._oc_l10n_registry_plural_functions[app] = plural;
	}
	// apps that ship no <lang>.json: mark them as loaded so core does not fetch a file that does not exist
	for (const app of DATA.noFile) {
		if (!Object.prototype.hasOwnProperty.call(real, app)) real[app] = {};
	}
	// Labels the server renders itself (app navigation entries and section captions arrive as finished text, so the
	// JS dictionary never sees them). Exact-text lookup, only inside these navigation elements: never user data.
	const NAV_TEXT = '.app-navigation-entry__name, .app-navigation-caption__name';
	const NAV_TITLE = '.app-navigation-entry-link[title]';
	const ORDER = ['core', 'lib', 'settings', 'files'];
	const lookup = (text) => {
		const reg = g._oc_l10n_registry_translations;
		const apps = [...ORDER, ...Object.keys(reg).filter((a) => !ORDER.includes(a))];
		for (const app of apps) {
			const v = reg[app]?.[text];
			if (typeof v === 'string' && v !== '' && v !== text) return v;
		}
		return null;
	};
	const fix = (root) => {
		if (!root.querySelectorAll) return;
		const nodes = root.matches?.(NAV_TEXT) ? [root, ...root.querySelectorAll(NAV_TEXT)] : root.querySelectorAll(NAV_TEXT);
		for (const el of nodes) {
			if (el.childNodes.length !== 1 || el.firstChild.nodeType !== 3) continue;
			const raw = el.firstChild.nodeValue; const text = raw.trim(); if (!text) continue;
			const tr = lookup(text); if (tr) el.firstChild.nodeValue = raw.replace(text, () => tr);
		}
		const links = root.matches?.(NAV_TITLE) ? [root, ...root.querySelectorAll(NAV_TITLE)] : root.querySelectorAll(NAV_TITLE);
		for (const el of links) { const tr = lookup(el.getAttribute('title').trim()); if (tr) el.setAttribute('title', tr); }
	};
	// English pages: Theming holds a single name and slogan (Arabic), so the server prints them in Arabic. Swap them for the
	// English wording in the page title and on guest pages (login, public pages: no user files shown there).
	const swapText = (text) => DATA.swaps.reduce((acc, [from, to]) => acc.split(from).join(to), text);
	const swapGuest = () => {
		if (DATA.swaps.length === 0) return;
		if (document.title) document.title = swapText(document.title);
		const id = document.body?.id; if (id !== 'body-login' && id !== 'body-public') return;
		const skip = '.files-list, #app-content-vue, .app-files';
		const walker = document.createTreeWalker(document.body, 4);
		const todo = [];
		for (let n = walker.nextNode(); n; n = walker.nextNode()) { if (n.parentElement && !n.parentElement.closest(skip) && !['SCRIPT', 'STYLE'].includes(n.parentElement.tagName)) todo.push(n); }
		for (const n of todo) { const t = swapText(n.nodeValue); if (t !== n.nodeValue) n.nodeValue = t; }
	};
	// Guest pages (login, public shares): a link to the other language. Signed-in users change language in their settings.
	const guestSwitch = () => {
		const id = document.body?.id; if (id !== 'body-login' && id !== 'body-public') return;
		const other = DATA.lang === 'ar' ? 'en' : 'ar';
		const a = document.createElement('a');
		a.className = 'pathlocale-switch'; a.lang = other; a.textContent = other === 'ar' ? 'العربية' : 'English';
		a.href = (g.OC?.webroot ?? '') + '/index.php/apps/pathlocale/lang/' + other + '?redirect=' + encodeURIComponent(location.pathname + location.search);
		document.body.appendChild(a);
	};
	const start = () => {
		fix(document.body);
		swapGuest();
		guestSwitch();
		let queued = false;
		new MutationObserver(() => { if (queued) return; queued = true; requestAnimationFrame(() => { queued = false; fix(document.body); swapGuest(); }); })
			.observe(document.body, { childList: true, subtree: true });
	};
	if (document.body) start(); else document.addEventListener('DOMContentLoaded', start, { once: true });
})();
